CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  age INTEGER NOT NULL
);
INSERT INTO users (name, age) VALUES ('washi', 30);
INSERT INTO users (name, age) VALUES ('''; DROP TABLE users; --', 30);
INSERT INTO users (name, age) VALUES ('taro', 25);
INSERT INTO users (name, age) VALUES ('O''Brien', 33);

package main

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"regexp"
	"strconv"
	"strings"
)

// ---- ここから下は「PostgreSQL の代わり」。変えなくてよい ----

type fakeDB struct {
	names   []string
	dropped bool
}

var insertRe = regexp.MustCompile(`^INSERT INTO users \(name, age\) VALUES \('([^']*)', (\d+)\) RETURNING id$`)

// QueryRow は db.QueryRow(...).Scan(&id) の代わり。採番された id を返す
func (d *fakeDB) QueryRow(query string, args ...any) (int, error) {
	if d.dropped {
		return 0, errors.New(`relation "users" does not exist`)
	}
	if query == "INSERT INTO users (name, age) VALUES ($1, $2) RETURNING id" {
		if len(args) != 2 {
			return 0, fmt.Errorf("expected 2 arguments, got %d", len(args))
		}
		name, ok1 := args[0].(string)
		_, ok2 := args[1].(int)
		if !ok1 || !ok2 {
			return 0, errors.New("invalid input syntax")
		}
		d.names = append(d.names, name) // 値は「ただのデータ」として保存される
		return len(d.names), nil
	}
	// プレースホルダーを使わない SQL は、文字列をそのまま SQL として解釈する
	stmts := strings.Split(query, ";")
	for _, s := range stmts[1:] {
		if strings.Contains(s, "DROP TABLE users") {
			d.dropped = true
		}
	}
	m := insertRe.FindStringSubmatch(stmts[0])
	if m == nil {
		return 0, errors.New("syntax error")
	}
	d.names = append(d.names, m[1])
	return len(d.names), nil
}

var db = &fakeDB{}

// ---- ここまで ----

// この createUser は SQL インジェクションに弱い。プレースホルダーを使う形に直す
func createUser(name string, age int) (int, error) {
	ageStr := strconv.Itoa(age)
	return db.QueryRow("INSERT INTO users (name, age) VALUES ('" + name + "', " + ageStr + ") RETURNING id")
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		ageStr, name, ok := strings.Cut(sc.Text(), " ")
		age, err := strconv.Atoi(ageStr)
		if !ok || err != nil {
			continue
		}
		id, err := createUser(name, age)
		if err != nil {
			fmt.Println("500", err)
			continue
		}
		fmt.Printf("201 id=%d name=%s\n", id, name)
	}
	if db.dropped {
		fmt.Println("users table: dropped")
	} else {
		fmt.Printf("users table: %d rows\n", len(db.names))
	}
}

